import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../../components/common';
import './AttendancePage.css';

export default function AttendancePage({attendance,employees,checkIn,checkOut,todayKey,role,userId}) { const my=attendance.find(a=>a.date===todayKey&&a.employeeId===userId); return <div className="module-page module-page--attendance"><div className="page-heading"><div><div className="eyebrow">PEOPLE OPERATIONS</div><h1>Attendance & time</h1><p>Record your workday and review today's attendance entries.</p></div><div className="heading-actions"><button className="btn secondary" onClick={()=>window.print()}>⎙ Print report</button></div></div><div className="attendance-hero panel"><div className="attendance-intro"><span className="eyebrow">TODAY'S WORKDAY</span><h2>{new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</h2><p>Check in when you start, and check out when your workday ends.</p><div className="attendance-actions"><button className="btn primary" onClick={checkIn}>↘ Check in</button><button className="btn secondary" onClick={checkOut}>↗ Check out</button></div>{my&&<div className="check-status"><span className="live-dot"/> Checked in at <b>{my.checkIn}</b>{my.checkOut&&<> · Checked out at <b>{my.checkOut}</b></>}</div>}</div><div className="clock-art"><div className="clock-face"><span>9</span><span>12</span><span>3</span><span>6</span><i className="clock-hand hour"/><i className="clock-hand minute"/><i className="clock-pin"/></div></div></div><div className="stats-grid"><Stat label="Present today" value={attendance.filter(a=>a.status==='Present').length} change="Recorded check-ins" icon="✓" tone="green" foot="Not a verified location punch"/><Stat label="Team size" value={employees.length} change="Employee roster" icon="♙" tone="purple" foot="Configured employees"/><Stat label="Checked out" value={attendance.filter(a=>a.checkOut).length} change="End-of-day recorded" icon="◷" tone="blue" foot="Based on Firebase records"/><Stat label="Not checked out" value={attendance.filter(a=>!a.checkOut).length} change="May still be working" icon="!" tone="orange" foot="Confirm before payroll"/></div><div className="panel"><div className="panel-head"><div><h3>Today's attendance log</h3><p>{todayKey} · Firebase live data</p></div><span className="table-count">{attendance.length} records</span></div><div className="table-wrap"><table><thead><tr><th>TEAM MEMBER</th><th>DATE</th><th>CHECK-IN</th><th>CHECK-OUT</th><th>STATUS</th></tr></thead><tbody>{attendance.map((a,i)=><tr key={a.id}><td><div className="contact-cell"><div className={`tiny-avatar av-${i%4}`}>{a.name[0]}</div><b>{a.name}</b></div></td><td>{a.date}</td><td>{a.checkIn||'—'}</td><td>{a.checkOut||'—'}</td><td><Status value={a.status}/></td></tr>)}</tbody></table>{!attendance.length&&<Empty title="No attendance records today" desc="Use Check in to save an attendance record to Firebase."/>}</div></div><div className="notice">Attendance is saved to Firebase. GPS verification, device policy, overtime rules and server timestamps require additional backend implementation.</div></div>; }
